contract InvMutTest
{
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function depositTwice(uint amount1, uint amount2) public
    { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2);
        c.Deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == amount1 + amount2);
    }

    receive() external payable {}
    fallback() external payable {}
}

