// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _depositTwice(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        try c.Deposit{value: amount1}() {} catch { return; }
        try c.Deposit{value: amount2}() {} catch { return; }
        assertTrue(c.balances(address(this)) == amount1 + amount2);
    }

    function testFuzz_depositTwice(uint256 amount1, uint256 amount2) public {
        _depositTwice(amount1, amount2);
    }

    receive() external payable {}

    fallback() external payable {}
}
